100	                $@"CREATE INDEX {(ifNotExists ? "IF NOT EXISTS " : "")}""{indexName}"" ON {schema}.""{tableName}"" (""{columnName}"");"
101	            );
102	        }
103	
104	        // Only support creating HNSW index creation through the connector.
105	        var indexTypeName = indexKind switch
106	        {
107	            IndexKind.Hnsw => "hnsw",
108	            _ => throw new NotSupportedException($"Index kind '{indexKind}' is not supported for table creation. If you need to create an index of this type, please do so manually. Only HNSW indexes are supported through the vector store.")
109	        };
110	
111	        distanceFunction ??= PostgresConstants.DefaultDistanceFunction;  // Default to Cosine distance
112	
113	        var indexOps = distanceFunction switch
114	        {
